solution.solution.cpp:
#include <vector>

struct Rect { float x, y, w, h; };
struct MouseFrame { float x, y; bool down; };

std::vector<int> clickFrames(const Rect& button, const std::vector<MouseFrame>& frames)
{
    std::vector<int> clicks;
    bool active{ false };
    bool wasDown{ false };
    for (int i{ 0 }; i < static_cast<int>(frames.size()); ++i)
    {
        const MouseFrame& m{ frames[static_cast<std::size_t>(i)] };
        const bool hovered{ m.x >= button.x && m.x < button.x + button.w && m.y >= button.y && m.y < button.y + button.h };
        const bool pressed{ m.down && !wasDown };
        const bool released{ !m.down && wasDown };
        if (pressed && hovered) active = true;
        if (released && active)
        {
            if (hovered) clicks.push_back(i);
            active = false;
        }
        wasDown = m.down;
    }
    return clicks;
}

unitTests:
const Rect btn{ 10, 10, 100, 20 };
TEST("a simple click") { CHECK_EQ(clickFrames(btn, { { 50, 15, false }, { 50, 15, true }, { 50, 15, false } }), (std::vector<int>{ 2 })); }
TEST("dragged off before release") { CHECK(clickFrames(btn, { { 50, 15, true }, { 300, 15, true }, { 300, 15, false } }).empty()); }
TEST("dragged off and back") { CHECK_EQ(clickFrames(btn, { { 50, 15, true }, { 300, 15, true }, { 60, 20, true }, { 60, 20, false } }), (std::vector<int>{ 3 })); }
TEST("pressed elsewhere, released over it") { CHECK(clickFrames(btn, { { 0, 0, true }, { 50, 15, true }, { 50, 15, false } }).empty()); }
TEST("edges") { CHECK_EQ(clickFrames(btn, { { 10, 10, true }, { 10, 10, false } }), (std::vector<int>{ 1 })); CHECK(clickFrames(btn, { { 110, 15, true }, { 110, 15, false } }).empty()); }
TEST("two clicks") { CHECK_EQ(clickFrames(btn, { { 20, 12, true }, { 20, 12, false }, { 20, 12, false }, { 30, 12, true }, { 30, 12, false } }), (std::vector<int>{ 1, 4 })); }
TEST("held from the start counts as a press") { CHECK_EQ(clickFrames(btn, { { 50, 15, true }, { 50, 15, false } }), (std::vector<int>{ 1 })); }

